import Foundation
import Testing
@testable import Purge

/// Playwright builds no installed Playwright uses (#328). Every fixture is a
/// throwaway home folder, laid out as Playwright lays out `ms-playwright`.
private enum Playwright {
    typealias Policy = PlaywrightBuildScanPolicy

    static let root = "Library/Caches/ms-playwright"

    /// `browsers.json` from playwright-core 1.65.0, trimmed to the fields Purge reads.
    static let browsersJSON165 = """
    {
      "comment": "Do not edit this file, use utils/roll_browser.js",
      "browsers": [
        { "name": "chromium", "revision": "1254", "installByDefault": true },
        { "name": "chromium-headless-shell", "revision": "1254", "installByDefault": true },
        { "name": "firefox", "revision": "1572", "installByDefault": true },
        {
          "name": "webkit", "revision": "2388", "installByDefault": true,
          "revisionOverrides": { "mac14": "2251", "mac14-arm64": "2251" }
        },
        { "name": "ffmpeg", "revision": "1013", "installByDefault": true },
        { "name": "winldd", "revision": "1007", "installByDefault": false },
        { "name": "android", "revision": "1001", "installByDefault": false }
      ]
    }
    """

    static func browsersJSON(_ entries: [(String, String)]) -> String {
        let list = entries.map { #"{ "name": "\#($0.0)", "revision": "\#($0.1)" }"# }.joined(separator: ", ")
        return #"{ "browsers": [\#(list)] }"#
    }

    static func makeHome() throws -> URL {
        let url = FileManager.default.temporaryDirectory
            .appendingPathComponent("purge-test-328-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: url, withIntermediateDirectories: true)
        return url.standardizedFileURL
    }

    static func folders(_ home: URL, _ relatives: [String]) throws {
        for relative in relatives {
            try FileManager.default.createDirectory(
                at: home.appendingPathComponent(relative),
                withIntermediateDirectories: true
            )
        }
    }

    static func write(_ text: String, _ home: URL, _ relative: String) throws {
        let url = home.appendingPathComponent(relative)
        try FileManager.default.createDirectory(at: url.deletingLastPathComponent(), withIntermediateDirectories: true)
        try Data(text.utf8).write(to: url)
    }

    /// A copy of `playwright-core` at `package` (relative to home) with this
    /// `browsers.json`, and the link Playwright writes for it in `root`.
    static func install(
        _ home: URL,
        package: String,
        browsersJSON: String,
        root: String = root,
        linkName: String? = nil
    ) throws {
        try write(browsersJSON, home, "\(package)/browsers.json")
        try write(home.appendingPathComponent(package).path, home, "\(root)/.links/\(linkName ?? UUID().uuidString)")
    }

    /// A link to a copy that isn't on disk.
    static func danglingLink(_ home: URL, root: String = root) throws {
        try write(home.appendingPathComponent("gone/node_modules/playwright-core").path, home, "\(root)/.links/gone")
    }

    /// Two copies' worth of builds: 1.65's, plus an older Chromium and headless
    /// shell, Playwright's own folders, and a folder of another tool.
    static func layBuilds(_ home: URL, root: String = root) throws {
        try folders(home, [
            "chromium-1200", "chromium-1254", "chromium_headless_shell-1200", "chromium_headless_shell-1254",
            "firefox-1572", "webkit-2388", "webkit-2251", "webkit_mac14_arm64_special-2251", "ffmpeg-1011", "ffmpeg-1013",
            "chromium-1254/chrome-mac-arm64", "__dirlock-not", "b", "mcp-chrome-4a3f9e"
        ].map { "\(root)/\($0)" })
    }

    static func offered(
        _ home: URL,
        _ relative: String,
        now: Date = Date(),
        access: ScanAccess = .full
    ) -> Bool {
        !Policy.refusesDeletion(home.appendingPathComponent(relative), home: home.path, now: now, access: access)
    }

    /// The build folder names the row lists, in order.
    static func rows(_ home: URL, now: Date = Date(), access: ScanAccess = .full) -> [String] {
        let definitions = Policy.definitions(home: home, access: access, now: now)
        #expect(definitions.count <= 1)
        for definition in definitions { #expect(definition.label == Policy.label) }
        return definitions.flatMap(\.paths).map(\.lastPathComponent)
    }
}

@Suite("Playwright builds (#328): only builds no link names")
struct PlaywrightBuildTests {
    typealias Policy = PlaywrightBuildScanPolicy

    @Test
    func offersOnlyBuildsNoLinkNames() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "app/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)

        #expect(Playwright.rows(home) == ["chromium-1200", "chromium_headless_shell-1200", "ffmpeg-1011"])
        for build in ["chromium-1200", "chromium_headless_shell-1200", "ffmpeg-1011"] {
            #expect(Playwright.offered(home, "\(Playwright.root)/\(build)"), "\(build)")
        }
        // `webkit-2251` is named only through 1.65's revision override for mac14.
        for kept in [
            "chromium-1254", "chromium_headless_shell-1254", "firefox-1572", "webkit-2388",
            "webkit-2251", "ffmpeg-1013",
        ] {
            #expect(!Playwright.offered(home, "\(Playwright.root)/\(kept)"), "\(kept)")
        }
    }

    @Test
    func neverOffersAnythingButABuildFolder() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "app/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)
        try Playwright.write("", home, "\(Playwright.root)/__dirlock")
        try FileManager.default.setAttributes(
            [.modificationDate: Date().addingTimeInterval(-3 * 60 * 60)],
            ofItemAtPath: home.appendingPathComponent("\(Playwright.root)/__dirlock").path
        )

        for relative in [
            Playwright.root, "\(Playwright.root)/.links", "\(Playwright.root)/__dirlock",
            "\(Playwright.root)/b", "\(Playwright.root)/mcp-chrome-4a3f9e", "\(Playwright.root)/__dirlock-not",
            "\(Playwright.root)/chromium-1200/chrome-mac-arm64", "\(Playwright.root)/chromium-1254/chrome-mac-arm64",
        ] {
            #expect(!Playwright.offered(home, relative), "\(relative)")
        }
        let links = try FileManager.default.contentsOfDirectory(atPath: home.appendingPathComponent("\(Playwright.root)/.links").path)
        for link in links {
            #expect(!Playwright.offered(home, "\(Playwright.root)/.links/\(link)"))
        }
        // The stale lock is left by a killed install, so the unused build is still offered.
        #expect(Playwright.offered(home, "\(Playwright.root)/chromium-1200"))
    }

    @Test
    func everyLinkKeepsWhatItNames() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "new/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)
        try Playwright.install(
            home,
            package: "old/node_modules/playwright-core",
            browsersJSON: Playwright.browsersJSON([("chromium", "1200"), ("chromium-headless-shell", "1200")])
        )
        #expect(Playwright.rows(home) == ["ffmpeg-1011"])
        #expect(!Playwright.offered(home, "\(Playwright.root)/chromium-1200"))
        #expect(!Playwright.offered(home, "\(Playwright.root)/chromium_headless_shell-1200"))
    }

    /// Anything unclear keeps every build, even ones no readable link names.
    @Test(arguments: [
        "no links folder", "empty links folder", "only Finder's file", "link is a folder", "link is a symlink",
        "relative path", "trailing newline", "copy is gone", "no browsers.json", "not JSON", "no browsers list",
        "entry without a revision", "revision is a number", "overrides are not text", "fresh lock",
    ])
    func unclearKeepsEveryBuild(_ scenario: String) throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        let root = Playwright.root
        let package = "app/node_modules/playwright-core"
        let fm = FileManager.default
        if scenario != "no links folder" {
            try Playwright.folders(home, ["\(root)/.links"])
        }
        // A readable copy as well, except where the scenario is about having none.
        if !["no links folder", "empty links folder", "only Finder's file"].contains(scenario) {
            try Playwright.install(home, package: package, browsersJSON: Playwright.browsersJSON165)
        }
        func json(_ text: String) throws {
            try Playwright.install(home, package: "other/node_modules/playwright-core", browsersJSON: text)
        }
        switch scenario {
        case "only Finder's file":
            try Playwright.write("", home, "\(root)/.links/.DS_Store")
        case "link is a folder":
            try Playwright.folders(home, ["\(root)/.links/folder"])
        case "link is a symlink":
            try fm.createSymbolicLink(
                atPath: home.appendingPathComponent("\(root)/.links/symlink").path,
                withDestinationPath: home.appendingPathComponent(package).path
            )
        case "relative path":
            try Playwright.write("app/node_modules/playwright-core", home, "\(root)/.links/relative")
        case "trailing newline":
            try Playwright.write(home.appendingPathComponent(package).path + "\n", home, "\(root)/.links/newline")
        case "copy is gone":
            try Playwright.danglingLink(home)
        case "no browsers.json":
            try Playwright.folders(home, ["empty/node_modules/playwright-core"])
            try Playwright.write(
                home.appendingPathComponent("empty/node_modules/playwright-core").path,
                home,
                "\(root)/.links/empty"
            )
        case "not JSON":
            try json("{ browsers: ")
        case "no browsers list":
            try json(#"{ "comment": "none" }"#)
        case "entry without a revision":
            try json(#"{ "browsers": [{ "name": "chromium" }] }"#)
        case "revision is a number":
            try json(#"{ "browsers": [{ "name": "chromium", "revision": 1200 }] }"#)
        case "overrides are not text":
            try json(#"{ "browsers": [{ "name": "webkit", "revision": "2388", "revisionOverrides": { "mac14": 2251 } }] }"#)
        case "fresh lock":
            try Playwright.write("", home, "\(root)/__dirlock")
        default:
            break
        }
        #expect(Playwright.rows(home).isEmpty, "\(scenario)")
        #expect(!Playwright.offered(home, "\(root)/chromium-1200"), "\(scenario)")
        #expect(!Playwright.offered(home, "\(root)/ffmpeg-1011"), "\(scenario)")
    }

    /// Reading a project in Documents without Full Disk Access would prompt, so the
    /// limited scan and the gate keep every build. With access they read it.
    @Test
    func protectedCopyNeedsFullDiskAccess() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "Documents/app/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)

        #expect(Playwright.rows(home, access: .limited).isEmpty)
        #expect(!Playwright.offered(home, "\(Playwright.root)/chromium-1200", access: .limited))
        #expect(Playwright.rows(home, access: .full) == ["chromium-1200", "chromium_headless_shell-1200", "ffmpeg-1011"])
        #expect(Playwright.offered(home, "\(Playwright.root)/chromium-1200", access: .full))
    }

    /// The Linux spelling is judged by its own links.
    @Test
    func dotCacheFolderUsesItsOwnLinks() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        let dotCache = ".cache/ms-playwright"
        try Playwright.layBuilds(home)
        try Playwright.layBuilds(home, root: dotCache)
        try Playwright.install(home, package: "app/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)
        try Playwright.install(
            home,
            package: "app/node_modules/playwright-core",
            browsersJSON: Playwright.browsersJSON165,
            root: dotCache
        )
        try Playwright.danglingLink(home, root: dotCache)

        #expect(Playwright.rows(home) == ["chromium-1200", "chromium_headless_shell-1200", "ffmpeg-1011"])
        #expect(!Playwright.offered(home, "\(dotCache)/chromium-1200"))
        #expect(!Playwright.offered(home, dotCache))
    }

    @Test
    func linkedFolderIsNeverRead() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home, root: "elsewhere/ms-playwright")
        try Playwright.install(
            home,
            package: "app/node_modules/playwright-core",
            browsersJSON: Playwright.browsersJSON165,
            root: "elsewhere/ms-playwright"
        )
        try Playwright.folders(home, ["Library/Caches"])
        try FileManager.default.createSymbolicLink(
            atPath: home.appendingPathComponent(Playwright.root).path,
            withDestinationPath: home.appendingPathComponent("elsewhere/ms-playwright").path
        )
        #expect(Playwright.rows(home).isEmpty)
        #expect(!Playwright.offered(home, "\(Playwright.root)/chromium-1200"))
    }

    /// The shape `evaluate` allows: one build, never the folder or anything else
    /// in it. Checked against a made-up home, so no real folder is read.
    @Test
    func shapeAllowsOnlyBuildFolders() {
        let home = "/Users/someone"
        func allowed(_ relative: String) -> Bool {
            Policy.isWhitelistedPath("\(home)/\(relative)", home: home)
        }
        for build in ["chromium-1194", "chromium_headless_shell-1194", "chromium_tip_of_tree-1300", "firefox_beta-1400",
                      "ffmpeg-1011", "webkit-2215", "winldd-1007", "android-1001"] {
            #expect(allowed("Library/Caches/ms-playwright/\(build)"), "\(build)")
            #expect(allowed(".cache/ms-playwright/\(build)"), "\(build)")
        }
        for other in ["", "/.links", "/.links/0a1b2c", "/__dirlock", "/b", "/mcp-chrome-123", "/chromium-1194/chrome-mac",
                      "/webkit_mac14_arm64_special-2251", "/chromium-", "/chromium-12a", "/Chromium-1194",
                      "/chromium-headless-shell-1194", "/chromium-1194.zip"] {
            #expect(!allowed("Library/Caches/ms-playwright\(other)"), "\(other)")
            #expect(!allowed(".cache/ms-playwright\(other)"), "\(other)")
        }
        #expect(!allowed("Library/Caches/chromium-1194"))
    }

    /// A path in the folder spelled with other case is the same folder on the
    /// Mac's disk, and it is refused without reading anything.
    @Test
    func otherCaseSpellingIsRefused() {
        let home = "/Users/someone"
        for path in ["Library/Caches/MS-Playwright/chromium-1194", "library/caches/ms-playwright", ".Cache/ms-playwright/x"] {
            #expect(Policy.refusesDeletion(URL(fileURLWithPath: "\(home)/\(path)"), home: home, access: .full), "\(path)")
        }
        #expect(!Policy.refusesDeletion(URL(fileURLWithPath: "\(home)/Library/Caches/Yarn"), home: home, access: .full))
    }

    @Test
    func overridesKeepTheirSpecialFolders() throws {
        let folders = try #require(Policy.buildFolders(inBrowsersJSON: Data(Playwright.browsersJSON165.utf8)))
        #expect(folders.isSuperset(of: [
            "chromium-1254", "chromium_headless_shell-1254", "firefox-1572", "webkit-2388",
            "webkit_mac14_special-2251", "webkit_mac14_arm64_special-2251", "webkit-2251", "ffmpeg-1013",
            "winldd-1007", "android-1001",
        ]))
    }

    /// `~/.cache/ms-playwright` used to be allowed as a whole. Only its builds are now.
    /// Paths only: none of them is read.
    @Test
    func evaluateAllowsBuildsAndNotTheDotCacheFolder() {
        func evaluate(_ relative: String) -> DeletionSafetyDecision {
            DeletionSafetyPolicy.evaluate(URL(fileURLWithPath: "\(DeletionSafetyPolicy.cachedHomePath)/\(relative)"))
        }
        #expect(evaluate(".cache/ms-playwright") != .allow)
        #expect(evaluate(".cache/ms-playwright/.links") != .allow)
        #expect(evaluate(".cache/ms-playwright/chromium-1194") == .allow)
    }

    /// A made-up home, so no real folder is listed.
    @Test
    func rowIsCheckFirstAndAppCachesStaysOffTheFolders() {
        let info = DevScanner.automaticSafetyInfo(forDevToolLabel: Policy.label, primaryPath: nil)
        #expect(info.level == .medium)
        #expect(info.headline == "Unused Playwright Browsers")
        let home = URL(fileURLWithPath: "/Users/someone", isDirectory: true)
        let claimed = DevScanner.claimedRoots(home: home).map(\.path)
        for root in Policy.roots {
            #expect(claimed.contains("/Users/someone/\(root)"), "\(root)")
        }
    }

    /// `evaluate` allows all of `~/Library/Caches/ms-playwright` through the Caches
    /// prefix, so `isOfferedForCleanup` alone refuses the rest of the folder. These
    /// are refused by their shape before anything is read.
    @Test
    func isOfferedForCleanupRefusesEverythingButBuilds() {
        let home = DeletionSafetyPolicy.cachedHomePath
        for root in Policy.roots {
            for relative in ["", "/.links", "/.links/0a1b2c3d", "/__dirlock", "/b", "/mcp-chrome-4a3f9e",
                             "/chromium-1194/chrome-mac-arm64", "/webkit_mac14_arm64_special-2251"] {
                let url = URL(fileURLWithPath: "\(home)/\(root)\(relative)")
                #expect(!DeletionSafetyPolicy.isOfferedForCleanup(url), "\(root)\(relative)")
            }
        }
    }

    /// A link that leads to another volume keeps every build, with or without
    /// access, and nothing on that volume is looked at.
    @Test(arguments: [
        "/Volumes/purge-test-328/app/node_modules/playwright-core",
        "/Network/Servers/purge-test-328/app/node_modules/playwright-core",
        "/net/purge-test-328/app/node_modules/playwright-core",
        "through a link",
    ])
    func otherVolumeKeepsEveryBuild(_ target: String) throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "app/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)
        var linkTarget = target
        if target == "through a link" {
            // `~/Work` points at a drive. The link is read, the drive is not.
            try FileManager.default.createSymbolicLink(
                atPath: home.appendingPathComponent("Work").path,
                withDestinationPath: "/Volumes/purge-test-328"
            )
            linkTarget = home.appendingPathComponent("Work/app/node_modules/playwright-core").path
        }
        try Playwright.write(linkTarget, home, "\(Playwright.root)/.links/drive")
        for access in [ScanAccess.limited, .full] {
            #expect(Playwright.rows(home, access: access).isEmpty, "\(target) \(access)")
            #expect(!Playwright.offered(home, "\(Playwright.root)/chromium-1200", access: access), "\(target) \(access)")
        }
    }

    /// The on-screen filter may answer from a read under `recentReadLifetime`
    /// seconds old. Every other caller reads the links again.
    @Test
    func onlyTheOnScreenFilterReusesARecentRead() throws {
        let home = try Playwright.makeHome()
        defer { try? FileManager.default.removeItem(at: home) }
        try Playwright.layBuilds(home)
        try Playwright.install(home, package: "new/node_modules/playwright-core", browsersJSON: Playwright.browsersJSON165)
        let build = home.appendingPathComponent("\(Playwright.root)/chromium-1200")
        let now = Date()
        func refused(after seconds: TimeInterval, reuse: Bool) -> Bool {
            Policy.refusesDeletion(build, home: home.path, now: now.addingTimeInterval(seconds), access: .full, reuseRecentRead: reuse)
        }
        #expect(!refused(after: 0, reuse: true))
        // A copy pinned to the old build installs.
        try Playwright.install(
            home,
            package: "old/node_modules/playwright-core",
            browsersJSON: Playwright.browsersJSON([("chromium", "1200")])
        )
        #expect(refused(after: 1, reuse: false))
        #expect(!refused(after: 1, reuse: true))
        #expect(refused(after: Policy.recentReadLifetime + 1, reuse: true))
    }
}
